function EXTRA(R,ICON){
 /* hook: a router on its capacitor through a power blink, and that capacitor's voltage draining (computed exponential) */
 ICON.ctRouter=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_T(20,36,'power blink: router still on',{fs:24,fw:800,fill:BLU})}<rect x="40" y="70" width="170" height="60" rx="12" fill="#343A40"/>${CT_L(70,70,58,46,'#343A40',5)}${CT_L(180,70,192,46,'#343A40',5)}${[0,1,2,3].map(i=>CT_dot(70+i*36,100,i<3?'#69DB7C':'#FFD43B',7)).join('')}${CT_cap(240,360,100,ORG)}${CT_T(300,150,'C',{fs:22,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.ctDrain=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CT_T(20,36,'its voltage drains away',{fs:24,fw:800,fill:ORG})}${CT_L(30,140,360,140,CT_AX,2)}${CT_L(30,52,30,140,CT_AX,2)}${CT_curve(t=>Math.exp(-t),0,4,30,360,140,84,ORG,5)}${CT_T(250,90,'how fast?',{fs:24,fw:800,fill:CT_MUT})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctRecapSwitch=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="320" rx="18" fill="#EDF2FF"/>${`<g transform="translate(0 0) scale(1.4)">${CT_coil(10,120,70,BLU,4)}</g>`}${CT_arrow(180,98,240,98,CT_INK,4)}${CT_isH(320,98,40,BLU)}${CT_T(320,176,'iL(0⁻)',{fs:30,fw:800,a:'middle',fill:BLU})}${`<g transform="translate(0 0) scale(1.4)">${CT_cap(10,120,175,ORG,4)}</g>`}${CT_arrow(180,245,240,245,CT_INK,4)}${CT_vs(320,245,40,ORG)}${CT_T(320,318,'vC(0⁻)',{fs:30,fw:800,a:'middle',fill:ORG})}</g>`;
 ICON.ctRecapDecay=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_L(20,300,410,300,CT_AX,2)}${CT_L(20,30,20,300,CT_AX,2)}${CT_curve(t=>Math.exp(-t),0,5,20,410,300,250,ORG,6)}${CT_L(20,50,98,300,CT_INK,3,'stroke-dasharray="8 6"')}${CT_dot(98,300-250*Math.exp(-1),ORG,8)}${CT_T(116,196,'36.8 % at τ',{fs:30,fw:800,fill:ORG})}${CT_T(98,330,'τ',{fs:28,fw:800,a:'middle',fill:CT_MUT})}</g>`;
 ICON.ctRecapStep=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${CT_L(20,190,410,190,CT_AX,2)}${CT_L(20,40,410,40,GRN,4,'stroke-dasharray="10 6"')}${CT_T(410,30,'forced',{fs:26,fw:800,a:'end',fill:GRN})}${CT_curve(t=>-Math.exp(-t),0,5,20,410,190,140,ORG,5)}${CT_T(410,320,'natural',{fs:26,fw:800,a:'end',fill:ORG})}${CT_curve(t=>1-Math.exp(-t),0,5,20,410,190,150,BLU,6)}${CT_T(200,110,'complete',{fs:26,fw:800,fill:BLU})}</g>`;
}
